INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 3, 'Gute Bewertung', 'Ich nehme die Creme erst seit ein paar Tagen, eine Verbesserung meiner Haut kann ich noch nicht feststellen, aber das dauert ja auch immer etwas… aber zumindest wird meine Haut durch die Creme nicht schlimmer was sonst oft der Fall ist (feuerrote backen)… die Verpackung und die Aufmachung finde ich wahnsinnig hochwertig und schön. Den Sinn hinter dem selber zugeben der Zusatzstoffe hab ich noch nicht ganz verstanden, aber soll wohl so ein „ich hab das selber gemacht-Gefühl“ erzeugen.. durch die einfüllung mit der Pipette bleibt halt immer ein kleiner Rest drin der dann beim raus quetschen meist neben der Creme landet.. ich bin auf jedenfall auf die Wirkung gespannt..', 'approved', 0, 0, '2024-12-04 23:00:00');
