INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Richtig gute DMS-Creme', 'Ich wollte unbedingt eine DMS-Creme als. Barrierecreme und hab sie nun gefunden. Während andere Barrierecremes auf dem Markt noch herkömmliche Emulgatoren enthalten (z.B. Glyceryl Stearate Citrate), ist hier wirklich nur Phosphatidylcholin enthalten. Auf Niacinamid, einen Wirkstoff meiner Wahl, musste ich auf Grund des individualisierten Systems auch nicht verzichten. Meine Haut verträgt die Creme bisher sehr gut!', 'approved', 0, 0, '2025-08-18 06:26:26');
