INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'ich bin vollstens zufrieden', 'Ich habe diese individuelle Creme auf einer Messe kennengelernt und gekauft. Diese Creme ist wie für mich gemacht. Nachdem ich jahrelang viele andere, unterschiedliche Cremes ausprobiert habe, möchte ich keine andere mehr. Sie versorgt meine Haut mit allem, was sie braucht.   Auch das Waschgel ist super und hält seeehr lange. Daher ist auch das seinen Preis wert.', 'approved', 0, 0, '2025-12-06 11:41:51');
