INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Schon beim Öffnen der Sendung war ich begeistert über die liebevolle und wertige Verpackung und Aufmachung. Über den Vorgang, dass man selber die hochwertigen Öle unter die Basiscreme rührt, bekommt man einen guten Bezug zur Creme und den Inhaltsstoffen. Das hat mir persönlich richtig gut gefallen.  So war ich gespannt, ob sich dieser sehr positive Ersteindruck auch in der Pflege fortsetzt. JA, eine feine Cremekonsistenz, die gut einzieht und nicht auf der Hautoberfläche klebt. Ich habe ein tolles Hautgefühl. Ich nutze die Creme seit ca. 3 Wochen morgens und abends nach der Reinigung. Meine Haut hat sich bereits erholt und fühlt sich weich und entspannt an. Ich empfehle von Herzen diese Creme und werde definitiv mir noch weitere Produkte von herbsom zulegen.', 'approved', 0, 0, '2025-01-02 23:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'serum', 5, 'Gute Bewertung', 'Ich habe das komplette Set gekauft und benutze es seit zwei Wochen, meine Haut strahlt und hat überhaupt keine Pickel mehr.', 'approved', 0, 0, '2024-12-20 23:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Tolle Creme! Meine Hautbarriere war total geschädigt und ich hatte immer wieder Unreinheiten, aber trotzdem trockene Stellen. Das ist jetzt so gut wie weg. Ich bin sehr überzeugt und kaufe definitiv wieder.', 'approved', 0, 0, '2023-04-05 22:00:00');
