INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich liebe diese Creme! Absolut tolles Hautgefühl. Ich hatte vorher Unreinheiten und Pickel und das Gefühl, dass meine Haut sich damit nicht mehr selbst helfen konnte. Jetzt fühlt sich meine Hautbarriere wieder gestärkt an und meine Haut ist reiner geworden. Riesengroßes Dankeschön!🤍💆🏼', 'approved', 0, 0, '2022-07-31 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Die Creme ist angenehm aufzutragen, zieht sehr schnell ein und die Haut fühlt sich sehr gut an. Ich habe sie wegen meiner Rötungen bestellt, da hat sich leider noch nichts getan…aber ich glaube, das geht nicht so schnell', 'approved', 0, 0, '2022-07-14 22:00:00');
