INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Die Creme hat mich wirklich überzeugt. Ich hatte unter anderem Probleme mit Unreinheiten in der Tzone, die ich jetzt nicht mehr habe. Außerdem bietet es mir die Möglichkeit, verschiedene Wirkungen/ Wirkstoffe so zu kombinieren, wie ich sie benötige. Das habe ich in einer Creme bisher nicht gefunden.', 'approved', 0, 0, '2022-05-29 22:00:00');
