INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Wunderbares Produkt, was ich jederzeit nachkaufen würde! Außerdem möchte ich den tollen Service loben! Nachdem meine erste Bestellung leider geklaut wurde bzw. nicht angekommen ist, wurde mir sofort eine neue Bestellung via Gutschein zugesendet. Das war wahnsinnig freundlich und vor allem sehr kulant - vielen Dank dafür!', 'approved', 0, 0, '2022-06-23 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich habe jahrelang gar keine Hautcreme benutzt und merke erst jetzt wie gut das meiner Haut tut. Nach wenigen Wochen ist das jetzt ein ganz anderes Hautgefühl. Danke :)', 'approved', 0, 0, '2022-04-25 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Beste Creme! Nie wieder ohne ❤️', 'approved', 0, 0, '2022-04-26 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich benutze die Creme seit mittlerweile drei Wochen und bin mega happy :) Ich habe vorher noch nie so viel Geld für die Hautpflege ausgegeben, aber das Konzept von Herbsom, dass man eine exakt auf die eigenen Bedürfnisse zugeschnittene Creme erhält, hat mich überzeugt. Nach den drei Wochen sehe ich schon einige Veränderungen. Meine Haut ist insgesamt glatter und strahlender und auch die Poren haben sich verkleinert. Genau das wollte ich erreichen. Ich kann die Creme deshalb guten Gewissens weiterempfehlen :)
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Bisher super, zieht sehr schnell ein, fettet nicht und glänzt nicht.', 'approved', 0, 0, '2022-04-25 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich bin soo zufrieden mit dieser Creme - das ist jetzt meine zweite Bestellung. Meine Falten wurden sichtbar reduziert und der Teint ist viel ebenmäßiger. Und die Haut fühlt sich toll an nach der Pflege ✨', 'approved', 0, 0, '2022-04-15 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich bin absolut begeistert von der Herbsom-Creme. Meine Falten sind deutlich weniger geworden und meine Haut fühlt sich gesund und straff an. Das hatte ich schon lange nicht mehr! Ich habe direkt an meine Schwester gedacht und ihr auch einen Gutschein für eine Creme geschenkt. Das Geschenk ist extrem gut angekommen, sie war begeistert, dass sie sich die natürlichen Wirkstoffe selbst zusammenstellen kann. Jetzt ist sie auch fleißig am testen. Ich halte euch auf dem Laufenden!', 'approved', 0, 0, '2022-04-11 22:00:00');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Tolle Creme, ich fühle mich richtig wohl diese Creme zu benutzen mit den Gedanken tolle Inhaltsstoffe auf meine Haut einzucremen.', 'approved', 0, 0, '2022-04-03 22:00:00');
