INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'creme', 5, 'Gute Bewertung', 'Ich war noch nie von einer Creme so überzeugt! Habe auch wirklich schon etliche probiert, auch sehr teuere. Ich habe eine schwierige Haut mit Rosacea, Pigmentflecken etc. Diese Creme beruhigt und ist so angenehm auf der Haut, ich möchte keine andere mehr! Verbesserungsvorschläge wären nur: 1. würde gerne ein Abo abschließen können, dass ich „meine“ Creme z.B. alle 3 Monate automatisch zugeschickt bekomme 😁👍🏻 und 2. zwecks dem Umweltgedanken vll nur Sachen zum nachfüllen schicken, wenn man schon ein Glasfläschchen aus der ersten Bestellung zu Hause hat, das wäre top! ☺️👍🏻', 'approved', 0, 0, '2024-07-30 03:17:03');
