INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, '10/10', 'Ich durfte das Sonnenschutzfluid schon vorab testen und bin wirklich sehr zufrieden. Ich trage es täglich über meinem Serum und meine Haut fühlt sich den ganzen Tag leicht und gepflegt an. Andere Sonnencremes sind mir oft zu speckig und führen zu Unreinheiten. Das habe ich hier überhaupt nicht. Für mich eine klare 10/10!', 'approved', 0, 0, '2026-03-31 11:54:15');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, 'Super angenehm, toll!', 'Vielen Dank, dass ich die Sonnencreme testen durfte. Ich finde sie wirklich toll. Ich habe eher trockene Haut und komme trotzdem sehr gut mit der leichten Textur zurecht. Sie fühlt sich angenehm pflegend an und hinterlässt ein schönes, natürliches Finish. Für mich ist sie inzwischen ein fester Bestandteil meiner täglichen Routine geworden und gibt mir im Alltag ein sehr gutes Gefühl.', 'approved', 0, 0, '2026-03-31 12:01:29');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, 'Endlich eine Sonnencreme die nicht fettet', 'Mit den meisten Sonnecremes glänze ich und bin weiß. Ich habe den Sonnenschutz in den letzten Wochen getestet und die Textur ist super leicht. Auch perfekt unter Make-up. Und was ich auch ziemlich cool finde, dass ein Blaulichtfilter drin ist, ich arbeite viel am PC und sich dort gegen Blaulicht zu schützen ist toll. Habe ich bisher auch noch bei keiner anderen Sonnencreme gesehen. Bin rundum zufrieden.', 'approved', 0, 0, '2026-03-31 12:07:03');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, 'Gute Bewertung', 'Mega, auch beim Sport richtig angenehm. Kein Kleben, kein Schwitzen und kein komischer Geruch.', 'approved', 0, 0, '2026-03-31 15:31:54');
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, 'Gute Bewertung', 'Nutze Herbsom schon länger und die Sonnencreme jetzt seit ein paar Tagen täglich morgens.
INSERT INTO reviews (userId, productId, rating, title, content, status, helpfulCount, unhelpfulCount, createdAt) VALUES (0, 'sunscreen', 5, 'Mein einziges Hautpflegeprodukt', 'Ich bin 30 geworden und da denkt man als Mann auch auf einmal an die Hautpflege. Ich wollte eine Creme mit Sonnenschutz, die ich morgens auftrage und fertig. Bin mit dieser hier sehr zufrieden, erfüllt genau ihren Zweck. Man sieht nicht eingecremt aus und es läuft mir auch nicht in die Augen wenn ich Sport mache. Scheint so als würde ich erstmal bei der hier bleiben.', 'approved', 0, 0, '2026-04-07 13:43:32');
